const rows = $input.all().map(function(i){ return i.json; });
function esc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
let filas = '';
for (const r of rows) {
  const stock = Number(r.cantidad);
  const min = Number(r.stock_minimo);
  const agotado = stock <= 0;
  const estado = agotado ? 'AGOTADO' : ('Quedan ' + stock);
  const color = agotado ? '#dc2626' : '#b45309';
  filas += '<tr>'
    + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;color:#1f2937;font-weight:600;">' + esc(r.nombre) + '</td>'
    + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:center;color:' + color + ';font-weight:700;">' + estado + '</td>'
    + '<td style="padding:9px 12px;border-bottom:1px solid #e8e8f0;text-align:center;color:#6b7280;">' + min + '</td>'
    + '</tr>';
}
const n = rows.length;
const html = '<!DOCTYPE html><html><head><meta charset="UTF-8"></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:Helvetica,Arial,sans-serif;">'
  + '<div style="max-width:600px;margin:24px auto;background:#ffffff;border-radius:12px;overflow:hidden;border:1px solid #e5e7eb;">'
  + '<div style="background:linear-gradient(135deg,#111827,#1f2937);padding:24px 28px;">'
  + '<div style="font-size:22px;font-weight:800;letter-spacing:1px;color:#fbbf24;">PIXELVAULT</div>'
  + '<div style="font-size:12px;color:#9ca3af;margin-top:4px;letter-spacing:2px;text-transform:uppercase;">Alerta de stock</div>'
  + '</div>'
  + '<div style="padding:24px 28px;">'
  + '<p style="margin:0 0 6px;font-size:16px;color:#111827;">Hola admin,</p>'
  + '<p style="margin:0 0 16px;font-size:14px;color:#6b7280;">Estos ' + n + ' producto(s) llegaron a su minimo de stock y conviene reponer:</p>'
  + '<table style="width:100%;border-collapse:collapse;font-size:14px;">'
  + '<tr style="background:#f9fafb;"><th style="padding:9px 12px;text-align:left;color:#6b7280;font-size:11px;text-transform:uppercase;">Producto</th><th style="padding:9px 12px;text-align:center;color:#6b7280;font-size:11px;text-transform:uppercase;">Stock</th><th style="padding:9px 12px;text-align:center;color:#6b7280;font-size:11px;text-transform:uppercase;">Minimo</th></tr>'
  + filas
  + '</table>'
  + '</div>'
  + '<div style="padding:14px 28px;background:#f9fafb;font-size:11px;color:#9ca3af;text-align:center;">PIXELVAULT - Correo automatico, no responder.</div>'
  + '</div></body></html>';
return [{ json: { subject: 'PIXELVAULT - ' + n + ' producto(s) con stock bajo', admin_html: html, cuantos: n } }];
